import test from 'node:test';
import assert from 'node:assert/strict';
import {existsSync, readFileSync} from 'node:fs';
import {validateReport, filterTrials} from './report.js';

// Reports are generated by lab tools, not fixtures edited by the UI.
for (const kind of ['benchmark', 'crash']) {
  const path = new URL(`../reports/${kind}.json`, import.meta.url);
  test(`UI accepts generated ${kind}.json`, {skip: !existsSync(path)}, () => {
    const report = JSON.parse(readFileSync(path, 'utf8'));
    assert.equal(validateReport(kind, report), report);
    if (kind === 'benchmark') {
      for (const shape of Object.keys(report.by_shape)) {
        const trials = filterTrials(report.trials, shape);
        assert.equal(trials.length, report.by_shape[shape].trials);
        const graded = trials.filter(row => row.passed !== null);
        assert.equal(graded.length, report.by_shape[shape].graded_trials);
        if (graded.length) {
          assert.equal(graded.filter(row => row.passed).length / graded.length, report.by_shape[shape].pass_rate);
        }
      }
    } else {
      assert.equal(`${report.passed}/${report.count}`, report.crash_safety);
    }
  });
}
